// ValidateTenantInfoResponseBody runs the validations defined on
// TenantInfoResponseBody
func ValidateTenantInfoResponseBody(body *TenantInfoResponseBody) (err error) {
	if body.ID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("id", "body"))
	}
	if body.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "body"))
	}
	if body.Subdomain == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("subdomain", "body"))
	}
	if body.Status == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("status", "body"))
	}
	if body.ID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.id", *body.ID, goa.FormatUUID))
	}
	if body.Status != nil {
		if !(*body.Status == "active" || *body.Status == "inactive" || *body.Status == "suspended") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.status", *body.Status, []any{"active", "inactive", "suspended"}))
		}
	}
	return
}
